     1→import { NextRequest, NextResponse } from 'next/server';
     2→import getDb from '@/lib/db';
     3→
     4→// 화이트리스트: SQL 인젝션 방지
     5→const ALLOWED_FIELDS = new Set([
     6→  'college', 'department', 'confirm_rate_26', 'faculty_count_26',
     7→  'new_hires', 'retirees', 'upcoming_retirements',
     8→  'req_general', 'req_dedicated', 'req_external', 'req_total',
     9→  'invitation_field', 'request_reason',
    10→  'to_general', 'to_dedicated', 'to_external', 'to_total',
    11→  'adv_general', 'adv_dedicated', 'adv_external', 'adv_total',
    12→  'pres_general', 'pres_dedicated', 'pres_external', 'pres_total',
    13→  'assign_reason', 'hq_opinion', 'bigs',
    14→  'to_req_25', 'to_assign_25',
    15→  'hire_regular_25', 'hire_rolling_25', 'hire_total_25',
    16→  'note', 'remark',
    17→]);
    18→
    19→export async function PATCH(
    20→  req: NextRequest,
    21→  { params }: { params: { id: string } }
    22→): Promise<NextResponse> {
    23→  const id = Number(params.id);
    24→  if (!Number.isInteger(id) || id <= 0) {
    25→    return NextResponse.json({ error: '잘못된 ID' }, { status: 400 });
    26→  }
    27→
    28→  let body: Record<string, unknown>;
    29→  try {
    30→    body = await req.json();
    31→  } catch {
    32→    return NextResponse.json({ error: '요청 파싱 실패' }, { status: 400 });
    33→  }
    34→
    35→  const entries = Object.entries(body);
    36→  if (entries.length === 0) {
    37→    return NextResponse.json({ error: '수정할 필드가 없습니다' }, { status: 400 });
    38→  }
    39→
    40→  for (const [field] of entries) {
    41→    if (!ALLOWED_FIELDS.has(field)) {
    42→      return NextResponse.json({ error: `허용되지 않는 필드: ${field}` }, { status: 400 });
    43→    }
    44→  }
    45→
    46→  const setClauses = entries.map(([field]) => `${field} = ?`).join(', ');
    47→  const values = entries.map(([, val]) => (val === undefined ? null : String(val)));
    48→
    49→  try {
    50→    const db = getDb();
    51→    const result = db
    52→      .prepare(`UPDATE to_haejung SET ${setClauses}, updated_at = datetime('now') WHERE id = ?`)
    53→      .run([...values, id]);
    54→
    55→    if (result.changes === 0) {
    56→      return NextResponse.json({ error: '해당 ID가 없습니다' }, { status: 404 });
    57→    }
    58→    return NextResponse.json({ ok: true });
    59→  } catch (err) {
    60→    return NextResponse.json(
    61→      { error: err instanceof Error ? err.message : '수정 실패' },
    62→      { status: 500 }
    63→    );
    64→  }
    65→}
    66→

