     9→const mockPrepare = jest.fn().mockReturnValue({ run: mockRun, get: mockGet });
    10→const mockExec = jest.fn();
    11→const mockPragma = jest.fn();
    12→
    13→jest.mock('better-sqlite3', () => {
    14→  const MockDB = jest.fn().mockImplementation(() => ({
    15→    prepare: mockPrepare,
    16→    exec: mockExec,
    17→    pragma: mockPragma,
    18→  }));
    19→  return MockDB;
    20→});
