    28→import { PATCH } from '@/app/api/to-haejung/[id]/route';
    29→
    30→function makeRequest(body: unknown, id = '1') {
    31→  return new NextRequest(`http://localhost/api/to-haejung/${id}`, {
    32→    method: 'PATCH',
    33→    headers: { 'Content-Type': 'application/json' },
    34→    body: JSON.stringify(body),
    35→  });
    36→}
    37→
    38→describe('PATCH /api/to-haejung/[id]', () => {
    39→  beforeEach(() => jest.clearAllMocks());
    40→
    41→  it('returns 200 on valid field update', async () => {
    42→    const req = makeRequest({ college: '공과대학' });
    43→    const res = await PATCH(req, { params: { id: '1' } });
    44→    expect(res.status).toBe(200);
    45→    const data = await res.json();
    46→    expect(data.ok).toBe(true);
    47→  });
    48→
    49→  it('returns 400 for unknown field (whitelist enforcement)', async () => {
    50→    const req = makeRequest({ malicious_field: 'value' });
    51→    const res = await PATCH(req, { params: { id: '1' } });
    52→    expect(res.status).toBe(400);
    53→  });
    54→
    55→  it('returns 400 for empty body', async () => {
    56→    const req = makeRequest({});
    57→    const res = await PATCH(req, { params: { id: '1' } });
    58→    expect(res.status).toBe(400);
    59→  });
    60→
    61→  it('returns 400 for non-integer id', async () => {
    62→    const req = makeRequest({ college: '공과대학' }, 'abc');
    63→    const res = await PATCH(req, { params: { id: 'abc' } });
    64→    expect(res.status).toBe(400);
    65→  });
    66→
    67→  it('returns 404 when id does not exist', async () => {
    68→    mockRun.mockReturnValueOnce({ changes: 0 });
    69→    const req = makeRequest({ college: '공과대학' }, '999');
    70→    const res = await PATCH(req, { params: { id: '999' } });
    71→    expect(res.status).toBe(404);
    72→  });
    73→});
